func (this *Test_org_eclipse_swt_browser_Browser) Test_OpenWindow_Progress_Listener_ValidateEventOrder() {
	var childCompleted *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var visibilityShowed *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var eventOrder *jrt.List = jrt.CollectionsSynchronizedSet(jrt.NewList())
	var childShell *swt.Shell = swt.NewShellParentStyle(this.shell, swt.None)
	childShell.SetText("Child shell")
	childShell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
	this.browser.AddOpenWindowListener(&OpenWindowListenerFunc{fn: func(event *browser.WindowEvent) {
		var browserChild *browser.Browser = this.CreateBrowser(childShell, this.swtBrowserSettings)
		event.Browser = browserChild
		browserChild.AddVisibilityWindowListener(browser.VisibilityWindowListenerShowAdapter(func(event2 *browser.WindowEvent) {
			eventOrder.Add("Visibility.show")
			visibilityShowed.Set(true)
			childShell.Open()
		}))
		browserChild.AddProgressListener(browser.ProgressListenerCompletedAdapter(func(event2 *browser.ProgressEvent) {
			eventOrder.Add("Progress.completed")
			childCompleted.Set(true)
			browserChild.SetText("Child Browser!")
		}))
	}})
	this.shell.Open()
	this.browser.SetText("<html>\n<script type='text/javascript'>\nvar newWin = window.open('about:blank');\n</script>\n<body>This test uses javascript to open a new window.</body>\n</html>")
	var passed bool = this.WaitForPassCondition(func() bool {
		return visibilityShowed.Get() && childCompleted.Get()
	})
	var errMsg string = fmt.Sprintf("%s%t\nChildCompleted:%t", fmt.Sprintf("\nTest timed out.\nExpected true for the below, but have:\nVisibilityShowed:"), visibilityShowed.Get(), childCompleted.Get())
	junit.AssertTrue(passed, errMsg)
	junit.AssertEquals(jrt.ListOf("Visibility.show", "Progress.completed"), jrt.ListCopyOf(eventOrder))
}

