func (this *Test_org_eclipse_swt_browser_Browser) Test_VisibilityWindowListener_multiple_shells() {
	var secondChildCompleted *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var childCount *jrt.AtomicInteger = jrt.NewAtomicInteger(0)
	this.browser.AddOpenWindowListener(&OpenWindowListenerFunc{fn: func(event *browser.WindowEvent) {
		var childShell *swt.Shell = swt.NewShellParent(this.shell)
		childShell.SetText(fmt.Sprintf("Child shell %d", childCount.Get()))
		childShell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
		var browserChild *browser.Browser = this.CreateBrowser(childShell, this.swtBrowserSettings)
		event.Browser = browserChild
		browserChild.SetText("Child window")
		anon137 := &Test_org_eclipse_swt_browser_BrowserAnon16{}
		anon137.VisibilityWindowAdapter = browser.NewVisibilityWindowAdapter()
		anon137.invocationCount = jrt.NewAtomicInteger(1)
		anon137.childID = jrt.NewAtomicInteger(childCount.Get())
		anon137.fnShow = func(event *browser.WindowEvent) {
			if anon137.childID.Get() == 0 && anon137.invocationCount.Get() >= 2 {
				if event.Location != (nil) || event.Size != (nil) {
					junit.Fail("Child browser's visibility show listener should only be fired once")
				}
			}
			anon137.invocationCount.IncrementAndGet()
		}
		browserChild.AddVisibilityWindowListener(anon137)
		if childCount.Get() == 1 {
			anon138 := &Test_org_eclipse_swt_browser_BrowserAnon17{}
			anon138.ProgressAdapter = browser.NewProgressAdapter()
			anon138.fnCompleted = func(event *browser.ProgressEvent) {
				secondChildCompleted.Set(true)
			}
			browserChild.AddProgressListener(anon138)
		}
		childShell.Open()
		childCount.IncrementAndGet()
	}})
	this.shell.Open()
	this.browser.SetText("<html><script type='text/javascript'>window.open('about:blank');window.open('about:blank');</script>\n<body>This test uses javascript to open a new window.</body>\n</html>")
	var passed bool = this.WaitForPassCondition(secondChildCompleted.Get)
	var errMsg string = "\nTest timed out."
	junit.AssertTrue(passed, errMsg)
}

func (this *Test_org_eclipse_swt_browser_Browser) Test_VisibilityWindowListener_eventSize() {
	this.shell.SetSize(200, 300)
	var childCompleted *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var result *jrt.AtomicReference = jrt.NewAtomicReference(swt.NewPoint(0, 0))
	var childShell *swt.Shell = swt.NewShellParent(this.shell)
	childShell.SetSize(250, 350)
	childShell.SetText("Child shell")
	childShell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
	this.browser.AddOpenWindowListener(&OpenWindowListenerFunc{fn: func(event *browser.WindowEvent) {
		var browserChild *browser.Browser = this.CreateBrowser(childShell, this.swtBrowserSettings)
		browserChild.AddVisibilityWindowListener(browser.VisibilityWindowListenerShowAdapter(func(event2 *browser.WindowEvent) {
			this.testLog.Append(fmt.Sprintf("Visibilty show eventfired.\nEvent size: %v", event2.Size))
			result.Set(event2.Size)
			childShell.Open()
			childCompleted.Set(true)
		}))
		event.Browser = browserChild
		this.testLog.Append("openWindowListener fired")
	}})
	this.shell.Open()
	this.browser.SetText("<html>\n<script type='text/javascript'>\nwindow.open('javascript:\"Child Window\"','', \"height=200,width=300\")\n</script>\n<body>This test uses javascript to open a new window.</body>\n</html>")
	var finishedWithoutTimeout bool = this.WaitForPassCondition(childCompleted.Get)
	childShell.Dispose()
	var passed bool = false
	if !SwtTestUtilIsWindows {
		passed = finishedWithoutTimeout && jrt.Cast[*swt.Point](result.Get()).X != 0 && jrt.Cast[*swt.Point](result.Get()).Y != 0
	} else {
		passed = finishedWithoutTimeout && jrt.Cast[*swt.Point](result.Get()).X == 300 && jrt.Cast[*swt.Point](result.Get()).Y == 200
	}
	var errMsg string
	if finishedWithoutTimeout {
		errMsg = fmt.Sprintf("%s%d\nexpected height=100, actual:%d", fmt.Sprintf("Incorrect size received:\nexpected width=300, actual:"), jrt.Cast[*swt.Point](result.Get()).X, jrt.Cast[*swt.Point](result.Get()).Y)
	} else {
		errMsg = "test timed out. Child's visibility Window listener didn't trigger"
	}
	junit.AssertTrue(passed, errMsg)
}

