func (this *Test_org_eclipse_swt_browser_Browser) Test_setJavascriptEnabled_multipleInstances() {
	var pageLoadCount *jrt.AtomicInteger = jrt.NewAtomicInteger(1)
	var pageLoadCountSecondInstance *jrt.AtomicInteger = jrt.NewAtomicInteger(1)
	var instanceOneFinishedCorrectly *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var instanceTwoFinishedCorrectly *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var browserSecondInsance *browser.Browser = this.CreateBrowser(this.shell, this.swtBrowserSettings)
	this.browser.AddProgressListener(browser.ProgressListenerCompletedAdapter(func(event *browser.ProgressEvent) {
		if pageLoadCount.Get() == 1 {
			this.browser.SetJavascriptEnabled(false)
			pageLoadCount.Set(2)
			this.browser.SetText("First instance, second page (with javascript turned off)")
			pageLoadCountSecondInstance.Set(2)
			browserSecondInsance.SetText("Second instance, second page (javascript execution not changed)")
		} else {
			if pageLoadCount.Get() == 2 {
				pageLoadCount.Set(3)
				var shouldBeNull bool = this.browser.Evaluate("return true").(bool)
				junit.AssertNull(shouldBeNull)
				instanceOneFinishedCorrectly.Set(true)
			}
		}
	}))
	anon139 := &Test_org_eclipse_swt_browser_BrowserAnon18{}
	anon139.ProgressAdapter = browser.NewProgressAdapter()
	anon139.fnCompleted = func(event *browser.ProgressEvent) {
		if pageLoadCountSecondInstance.Get() == 2 {
			pageLoadCountSecondInstance.Set(3)
			var shouldBeTrue bool = browserSecondInsance.Evaluate("return true").(bool)
			junit.AssertTrue(shouldBeTrue)
			instanceTwoFinishedCorrectly.Set(true)
		}
	}
	browserSecondInsance.AddProgressListener(anon139)
	this.browser.SetText("First Instance, first page")
	browserSecondInsance.SetText("Second instance, first page")
	this.shell.Open()
	var passed bool = this.WaitForPassCondition(func() bool {
		return instanceOneFinishedCorrectly.Get() && instanceTwoFinishedCorrectly.Get()
	})
	var message string = fmt.Sprintf("%s%t\nInstanceTwoFinishedCorrectly: %t\nInstance 1 & 2 page counts: %d & %d", fmt.Sprintf("3) Test timed out. Debug Info:\nInstanceOneFinishedCorrectly: "), instanceOneFinishedCorrectly.Get(), instanceTwoFinishedCorrectly.Get(), pageLoadCount.Get(), pageLoadCountSecondInstance.Get())
	junit.AssertTrue(passed, message)
}

func (this *Test_org_eclipse_swt_browser_Browser) Test_LocationListener_evaluateInCallback() {
	var changingFinished *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var changedFinished *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	anon140 := &Test_org_eclipse_swt_browser_BrowserAnon19{}
	anon140.fnChanging = func(event *browser.LocationEvent) {
		this.browser.Evaluate("SWTchanging = true")
		changingFinished.Set(true)
	}
	anon140.fnChanged = func(event *browser.LocationEvent) {
		this.browser.Evaluate("SWTchanged = true")
		changedFinished.Set(true)
	}
	this.browser.AddLocationListener(anon140)
	this.shell.Open()
	this.browser.SetText("<body>Hello <b>World</b></body>")
	if SwtTestUtilIsWindows {
		this.WaitForPassCondition(changingFinished.Get)
	} else {
		this.WaitForPassCondition(func() bool {
			return (changingFinished.Get() && changedFinished.Get())
		})
	}
	var changed bool = false
	func() {
		defer func() {
			r := recover()
			if r == nil {
				return
			}
			if func() bool {
				switch r.(type) {
				case *swt.SWTException:
					return true
				}
				return false
			}() {
				e := r.(*swt.SWTException)
				_ = e
			} else {
				panic(r)
			}
		}()
		changed = this.browser.Evaluate("return SWTchanged").(bool)
	}()
	var changing bool = false
	func() {
		defer func() {
			r := recover()
			if r == nil {
				return
			}
			if func() bool {
				switch r.(type) {
				case *swt.SWTException:
					return true
				}
				return false
			}() {
				e := r.(*swt.SWTException)
				_ = e
			} else {
				panic(r)
			}
		}()
		changing = this.browser.Evaluate("return SWTchanging").(bool)
	}()
	var errMsg string = fmt.Sprintf("\n  changing:  fired:%t    evaluated:%t\n  changed:   fired:%t    evaluated:%t", changingFinished.Get(), changing, changedFinished.Get(), changed)
	var passed bool = false
	if SwtTestUtilIsGTK || SwtTestUtilIsCocoa {
		passed = changingFinished.Get() && changedFinished.Get() && changed
	} else {
		if SwtTestUtilIsWindows {
			passed = changingFinished.Get()
		}
	}
	junit.AssertTrue(passed, errMsg)
}

