func (this *Test_org_eclipse_swt_browser_Browser) Test_evaluate_invalid_return_value() {
	if SwtTestUtilIsWindows {
		return
	}
	var exception *jrt.AtomicInteger = jrt.NewAtomicInteger(-1)
	this.browser.AddProgressListener(browser.ProgressListenerCompletedAdapter(func(event *browser.ProgressEvent) {
		func() {
			defer func() {
				r := recover()
				if r == nil {
					return
				}
				if func() bool {
					switch r.(type) {
					case *swt.SWTException:
						return true
					}
					return false
				}() {
					e := r.(*swt.SWTException)
					_ = e
					exception.Set(e.Code)
				} else {
					panic(r)
				}
			}()
			this.browser.Evaluate("return new Date()")
		}()
	}))
	this.browser.SetText("<html><body>HelloWorld</body></html>")
	this.shell.Open()
	var wrongExceptionCode *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var passed bool = this.WaitForPassCondition(func() bool {
		if exception.Get() != -1 {
			if exception.Get() == swt.ERROR_INVALID_RETURN_VALUE {
				return true
			} else {
				if exception.Get() == swt.ERROR_FAILED_EVALUATE {
					wrongExceptionCode.Set(true)
					return true
				}
			}
		}
		return false
	})
	if wrongExceptionCode.Get() {
		fmt.Fprintln(os.Stderr, fmt.Sprintf("SWT Warning: test_evaluate_invalid_return_value threw wrong exception code. Expected ERROR_INVALID_RETURN_VALUE but got ERROR_FAILED_EVALUATE"))
	}
	var message string
	if exception.Get() == -1 {
		message = "Exception was not thrown. Test timed out"
	} else {
		message = fmt.Sprintf("Exception thrown, but wrong code: %d", exception.Get())
	}
	junit.AssertTrue(passed, message)
}

