func (this *Test_org_eclipse_swt_browser_Browser) WaitForPassConditionPassTestMillisecondsToWait(passTest func() bool, millisecondsToWait int32) bool {
	var passed *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	var timeOut *jrt.Instant = jrt.InstantNow().PlusMillis(int64(millisecondsToWait))
	var debug_showBrowserTimeout *jrt.Instant = jrt.InstantNow().PlusSeconds(int64(this.debug_show_browser_timeout_seconds))
	var display *swt.Display = this.shell.GetDisplay()
	jrt.ThreadStart(jrt.NewThread(jrt.NewRunnable(func() {
		for jrt.InstantNow().IsBefore(timeOut) {
			if passTest() {
				passed.Set(true)
				break
			}
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if func() bool {
						switch r.(type) {
						case *jrt.InterruptedException:
							return true
						}
						return false
					}() {
						e := r.(*jrt.InterruptedException)
						_ = e
						fmt.Fprintln(os.Stderr, e)
					} else {
						panic(r)
					}
				}()
				jrt.Sleep(int64(2))
			}()
		}
		for this.debug_show_browser && jrt.InstantNow().IsBefore(debug_showBrowserTimeout) {
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if func() bool {
						switch r.(type) {
						case *jrt.InterruptedException:
							return true
						}
						return false
					}() {
						e := r.(*jrt.InterruptedException)
						_ = e
						fmt.Fprintln(os.Stderr, e)
					} else {
						panic(r)
					}
				}()
				jrt.Sleep(int64(500))
			}()
		}
		display.Wake()
	})))
	for jrt.InstantNow().IsBefore(timeOut) {
		if passed.Get() {
			if !this.debug_show_browser {
				break
			}
			if jrt.InstantNow().IsAfter(debug_showBrowserTimeout) {
				break
			}
		}
		if !this.shell.IsDisposed() {
			if !display.ReadAndDispatch() {
				display.Sleep()
			}
		}
	}
	return passed.Get()
}

